const express = require("express");
const router = express.Router();
const controller = require("../controllers/livestockController");

router.post("/login", controller.login);

router.post("/farmer", controller.addFarmer);
router.post("/livestock", controller.addLivestock);
router.get("/livestock", controller.getLivestock);
router.delete("/livestock/:id", controller.deleteLivestock);
router.put("/livestock/:id", controller.updateLivestock);
router.get("/livestock/search", controller.searchLivestock);

module.exports = router;